// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const A = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const WORK = new Float64Array( 10 );

	dorgqr(); // $ExpectError
	dorgqr( 'column-major' ); // $ExpectError
	dorgqr( 'column-major', 3 ); // $ExpectError
	dorgqr( 'column-major', 3, 2 ); // $ExpectError
	dorgqr( 'column-major', 3, 2, 2 ); // $ExpectError
	dorgqr( 'column-major', 3, 2, 2, A ); // $ExpectError
	dorgqr( 'column-major', 3, 2, 2, A, 3 ); // $ExpectError
	dorgqr( 'column-major', 3, 2, 2, A, 3, TAU ); // $ExpectError
	dorgqr( 'column-major', 3, 2, 2, A, 3, TAU, WORK ); // $ExpectError
	dorgqr( 'column-major', 3, 2, 2, A, 3, TAU, WORK, 10, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	const A = new Float64Array( 6 );
	const TAU = new Float64Array( 2 );
	const WORK = new Float64Array( 10 );

	dorgqr.ndarray( 3, 2, 2, A, 1, 3, 0, TAU, 1, 0, WORK, 1, 0, 10 ); // $ExpectType number
}

