	dorgqr.ndarray( '5', 2, 2, A, 1, 3, 0, TAU, 1, 0, WORK, 1, 0, 10 ); // $ExpectError
	dorgqr.ndarray( true, 2, 2, A, 1, 3, 0, TAU, 1, 0, WORK, 1, 0, 10 ); // $ExpectError
